\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 89\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -90\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Exemplum}}\plain \f1\scaps\lang1033\fs24  de ortu rosarii\plain \f1\lang1033\fs24 . \u8250 \'9b\plain \f1\i\lang1033\fs24 Exemplum de rosario virginis gloriose\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Legitur in miraculis beate virginis Marie, quod fuit quidam devotus monachus}}\plain \f1\lang1033\fs24  ...-... \plain \f1\i\lang1033\fs24 dummodo ad unum annum devote compleverit.\plain \f1\lang1033\fs24  Lat. Fassung des Marienmirakels \ldblquote Marien Rosenkranz\rdblquote , vgl. Ulla Williams, in: VL\plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24  5, 1985, Sp. 1278-1280. Vgl. auch Andreas Heinz, Eine sp\u228 \'e4tmittelalterliche Exempelsammlung zur Propagierung des Trierer Kart\u228 \'e4user-Rosenkranzes (Bibl. Cusana Hs 128, fol. 134-141), in: Trierer Theologische Zeitschrift 92, 1983, S. 306-318, hier 312f., 317 zu Exemplum IV.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

