\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 90\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -98\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Rosarium BMV}}\plain \f1\lang1033\fs24 . \u8250 \'9b\plain \f1\i\lang1033\fs24 Ad rosarium istud beate Marie faciendum dicatur angelica salutacio quinquaginta vicibus et post quamlibet addatur una particula vite Jhesu infra signate \plain \f1\lang1033\fs24 (!)\plain \f1\i\lang1033\fs24  sive dicendo sive meditando prout placuerit\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Ave Maria, gracia plena ... (91r) Quem virgo sancta angelo nunciante de spiritu sancto concepisti}}\plain \f1\i\lang1033\fs24  amen\plain \f1\lang1033\fs24  ... (97\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Schlu\u223 \'dfgebet: {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Ihesus Cristus qui cum patre et spiritu sancto vivit}}\plain \f1\lang1033\fs24  ...-... \plain \f1\i\lang1033\fs24 sit in presenti gracia et in futuro vita eternam\plain \f1\lang1033\fs24  (!). \plain \f1\i\lang1033\fs24 Amen.\plain \f1\lang1033\fs24  (98\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[0]/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Disen Rosenkrancz von vnnser lieben frawen In lathin hat geschriben Junckfraw Margreth Schaffl\u250 \'faczlin Johannesen Schaffl\u250 \'faczls gerichtschreibers z\u252 \'fc N\u246 \'f6rdlingen eeliche tochter vnd geenndet vff afftermontag nach dem hailigen pallmtag des Jars alls man nach der geburd Christi vnnsers herren zallt tausend vierhunndert Sibenczigk vnd in dem Newnden Jare}}\plain \f1\lang1033\fs24  (6.4.1479)\u8249 \'8b. 50 Klauseln. Weitgehend \u252 \'fcbereinstimmend mit den sog. \u228 \'e4ltesten Rosenkranz-\ldblquote Clausulae\rdblquote  aus dem Umkreis der Trierer Kartause, s. Klinkhammer, Adolf von Essen, bes. S. 198-201, 203-205, 208-216, sowie 217 Nr 19 u. 223 Nr 31 f\u252 \'fcr einzelne Klauseln. - Zu Johannes Schaffl\u250 \'faczl vgl. die Notiz (aus dem Jahr 1465) \u252 \'fcber seine Bestellung zum Gerichtsschreiber im \ldblquote Diener- und Amtleutebuch, 1433-1480\rdblquote , in: Karl Otto M\u252 \'fcller, N\u246 \'f6rdlinger Stadtrechte des Mittelalters (Bayerische Rechtsquellen 2), M\u252 \'fcnchen 1933, S. 431 Nr 39.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

