\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 121\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -127\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 De periculis et defectibus contingentibus in missa et de remediis eorundem}}\plain \f1\lang1033\fs24 . (121\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -124\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Defectibus potest dupliciter obviari}}\plain \f1\lang1033\fs24  ...{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7  Primus defectus est, quod si sacerdos morte vel grave infirmitate occupetur}}\plain \f1\i\lang1033\fs24  ante consecracionem corporis et sangwinis domini\plain \f1\lang1033\fs24  ...-... \plain \f1\i\lang1033\fs24 fractio hostie. Ibidem arti. vi in solu. vi. argu.\plain \f1\lang1033\fs24  10 Defectus. Angeschlossen: (124\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -126\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Sequuntur nunc quatuor defectus, qui possunt contingere in missa, qui recompensari possunt penitenciam faciendo secundum statutum ecclesie et quomodo\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Primus defectus est, quod ille qui non bene custodierit hoc sacramentum}}\plain \f1\lang1033\fs24  ...-... \plain \f1\i\lang1033\fs24 cinere in sacrario posito sicut de rasura tabule dictum est.\plain \f1\lang1033\fs24  \u8250 \'9b\plain \f1\i\lang1033\fs24 Hec beatus Thomas iii parte summe q. 83 arti. vi. in solu. vii. argu. per totum et Rayne secunda parte Missa c. xv\plain \f1\lang1033\fs24 \u8249 \'8b. \u220 \'dcberwiegend w\u246 \'f6rtliche Exzerpte jeweils unter Angabe der Quelle aus: {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Thomas de Aquino}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Summa theologicae}}\plain \f1\lang1033\fs24 , P. III, q. 83, a. 6. Ed.: Opera omnia. Leonina, Bd 12, Rom 1906, S. 283b Z. 16 - S. 285b. Au\u223 \'dfer {\field{\*\fldinst HYPERLINK "hida://bezper[3].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Rayne(rus de Pisis}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Pantheologia}}\plain \f1\lang1033\fs24 ) werden in Randbemerkungen zitiert: (124\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Pe(trus) de Pa(lude)}}\plain \f1\lang1033\fs24 \u8249 \'8b, (125\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://bezper[4].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Raymundus\u8249 \'8b (de Pennaforti)}}\plain \f1\lang1033\fs24 , (125\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 . 127\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Anto(ninus Florentinus}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Summa moralis}}\plain \f1\lang1033\fs24 )\u8249 \'8b. Die Werke des Rainerus und Antoninus waren als Inkunabeln in Maihingen vorhanden, vgl. H\u228 \'e4gele, Birgitta, S. 376f.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Arial;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

