\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (59\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -64\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) [{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Orationes}}\plain \f1\scaps\lang1033\fs24  variae\plain \f1\lang1033\fs24 ]. (59\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Pro peccatis\plain \f1\lang1033\fs24 \u8249 \'8b. CO Nr 2541. \u8250 \'9b\plain \f1\i\lang1033\fs24 Pro quacumque necessitate\plain \f1\lang1033\fs24 \u8249 \'8b. Nr 3129. (59\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Generalis\plain \f1\lang1033\fs24 \u8249 \'8b. Nr 4227 (in der Hs ausf\u252 \'fchrlicher). (60\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Miserere nobis, domine, miserere nobis, miserere misericors et benedicta trinitas sancta}}\plain \f1\i\lang1033\fs24  et dimitte nobis universa delicta nostra\plain \f1\lang1033\fs24  ...-... \plain \f1\i\lang1033\fs24 ab omni malo preterito, presenti et futuro.\plain \f1\lang1033\fs24  Auszug aus: PL 101, Sp. 1390D; vgl. Haimerl, Gebetbuchliteratur, S. 10 mit Anm. 52. \u8250 \'9b\plain \f1\i\lang1033\fs24 Collecta\plain \f1\lang1033\fs24 \u8249 \'8b. (60\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Omnipotens sempiterne deus, te humiliter precor, ut me famulam tuam non perire permittas}}\plain \f1\lang1033\fs24  ... Vgl. Kat. Uppsala 7 (Reg.), S. 323.  {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Omnipotens mitissime deus, respice propicius super me miserrimam famulam tuam}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24  Vgl. Hs {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Uppsala, UB, C\~504, Fragm. II}}\plain \f1\lang1033\fs24 , 16\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , Kat. Uppsala 5, S. 255. \u8250 \'9b\plain \f1\i\lang1033\fs24 Pro vivis benefactoribus\plain \f1\lang1033\fs24 \u8249 \'8b. CO Nr 2015. (61\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Pro quacumque tribulacione\plain \f1\lang1033\fs24 \u8249 \'8b. Nr 3852. \u8250 \'9b[Pro] \plain \f1\i\lang1033\fs24 serenitate\plain \f1\lang1033\fs24 \u8249 \'8b. Nr 85. \u8250 \'9b\plain \f1\i\lang1033\fs24 Pro pluvia\plain \f1\lang1033\fs24 \u8249 \'8b. Nr 1242. (61\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Nur Textanf\u228 \'e4nge: Nr 3920. 1666. \plain \f1\i\lang1033\fs24 Sancta Maria mater domini nostri Ihesu Christe etc.\plain \f1\lang1033\fs24  Collins, Breviary, aaO., S. 26. \u8250 \'9b\plain \f1\i\lang1033\fs24 De angelis\plain \f1\lang1033\fs24 \u8249 \'8b. CO Nr 1798. \u8250 \'9b\plain \f1\i\lang1033\fs24 De omnibus sanctis\plain \f1\lang1033\fs24 \u8249 \'8b. Nr 4102. (62\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Pro pace\plain \f1\lang1033\fs24 \u8249 \'8b. Nr 1088a. \u8250 \'9b\plain \f1\i\lang1033\fs24 Pro predicantibus\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Corda famulorum tuorum, domine, illumina}}\plain \f1\lang1033\fs24  ...; \u8250 \'9b\plain \f1\i\lang1033\fs24 Pro infirmo\plain \f1\lang1033\fs24 \u8249 \'8b. Nr 4072. \u8250 \'9b\plain \f1\i\lang1033\fs24 Pro iter agentibus collecta\plain \f1\lang1033\fs24 \u8249 \'8b. Nr 151 (bricht unvollst\u228 \'e4ndig ab). (62\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Pro prelato oracio\plain \f1\lang1033\fs24 \u8249 \'8b. Variante zu Nr 3938c. \u8250 \'9b\plain \f1\i\lang1033\fs24 Pro rege\plain \f1\lang1033\fs24 \u8249 \'8b. Nr 1237.\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 Pro peticione lacrimarum\plain \f1\lang1033\fs24 \u8249 \'8b. Nr 3779. \u8250 \'9b\plain \f1\i\lang1033\fs24 Contra infideles\plain \f1\lang1033\fs24 \u8249 \'8b. Nr 3846-B. \u8250 \'9b\plain \f1\i\lang1033\fs24 Pro persequtoribus\plain \f1\lang1033\fs24  (!) \plain \f1\i\lang1033\fs24 ecclesie\plain \f1\lang1033\fs24 \u8249 \'8b. Nr 2404b. \u8250 \'9b\plain \f1\i\lang1033\fs24 Pro vivis et defunctis\plain \f1\lang1033\fs24 \u8249 \'8b. Nr 4064. \u8250 \'9b\plain \f1\i\lang1033\fs24 Oracio\plain \f1\lang1033\fs24 \u8249 \'8b. Nr 4524 (in der Hs ausf\u252 \'fchrlicher). (63\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Domine Ihesu Christe qui pro salute hominum ascendisti crucis patibulum\plain \f1\lang1033\fs24  ... Vgl. Bruylants 2, Nr 491. \u8250 \'9b\plain \f1\i\lang1033\fs24 Pro propriis peccatis\plain \f1\lang1033\fs24 \u8249 \'8b. CO Nr 1143. \u8250 \'9b\plain \f1\i\lang1033\fs24 Pro amico speciali\plain \f1\lang1033\fs24 \u8249 \'8b. Nr 3859. (64\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Pro amicis\plain \f1\lang1033\fs24 \u8249 \'8b. Nr 4587a. \u8250 \'9b\plain \f1\i\lang1033\fs24 Alia oracio pro amicis\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Omnipotens sempiterne deus, miserere famulis tuis vel famulo tuo per intercessionem beate Marie virginis}}\plain \f1\lang1033\fs24  ... U.a. auch Hs {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Uppsala, UB, C\~502}}\plain \f1\lang1033\fs24 , 23\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , Kat. Uppsala 5, S. 250. (64\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24