\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs20 Ia. Bl 1-2: {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat7 um 1480}}\plain \f0\fs20  \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  Wz: (Krone) Typus Br 4891 (1480) \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  Schriftraum 10 \plain \f2\lang1024\fs20 \u180 \'b4\plain \f0\fs20  6,5-7 \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  20 Zeilen \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  schlaufenlose {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat7 Bastarda}}\plain \f0\fs20 , von derselben Hand wie {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f0\fs20\chcbpat7 Theol. lat. oct. 72}}\plain \f0\fs20 , 1\plain \f1\super\lang1033\fs20 r\plain \f0\fs20 -20\plain \f1\super\lang1033\fs20 v\plain \f0\fs20  \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  rubriziert \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  wechselnd rote und blaue 1zeilige Majuskeln zu den Strophenanf\u228 \'e4ngen \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  1\plain \f1\super\lang1033\fs20 r\plain \f0\fs20  3zeilige blaue Lombarde mit braun-gelber F\u252 \'fcllung.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Ib. Bl 3: {\field{\*\fldinst HYPERLINK "hida://5060[1].5064/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat7 um 1485}}\plain \f0\fs20  \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  Wz: (Ochsenkopf) Typus PiccO XV 384/385 (1484-1489) \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  Schriftraum 10-10,5 \plain \f2\lang1024\fs20 \u180 \'b4\plain \f0\fs20  6,5 \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  20 Zeilen \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  Bastarda, teils mit Schlaufen, vermutlich von derselben Hand wie Bl 1-2 \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  rubriziert.
