\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 75\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -76\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  [{\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930gi/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Sermo] de purgatorio Patricii}}\plain \f1\lang1033\fs24 . \u8250 \'9b\plain \f1\i\lang1033\fs24 Purgatorium Patricij\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Post mortem beati Patricii fuit quidam prior in eadem ecclesia que dicitur Reglis}}\plain \f1\i\lang1033\fs24 , vir sancte conversacionis,\plain \f1\lang1033\fs24  ...-... \plain \f1\i\lang1033\fs24 Deinde signo crucis domini in humero suscepto, ad sepulcrum domini Ierosolimam perrexit, et cum venisset ad dominum suum, regem terre illius, virum prudentem, per eius consilium atque voluntatem suscepit habitum religionis, in qua postea religiose et sancte vixit, et sic vitam finiens migravit ad Christum, ad quem et nos pervenire mereamur\plain \f1\lang1033\fs24  ... Stark gek\u252 \'fcrzte Fassung von: [{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Henricus Salteriensis}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Tractatus de purgatorio sancti Patricii}}\plain \f1\lang1033\fs24 ]. Ed.: St Patrick\rquote s Purgatory. [...] Ed. by Robert Easting (Early English Text Society. Original Series 298), Oxford 1991, S. 125 Z. 154 - S. 150 Z. 1091. Vgl. BHL Nr 6510-6511.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

