\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 76\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -82\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24  [{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Petrus de Remis}}\plain \f1\scaps\lang1033\fs24 :\plain \f1\lang1033\fs24 ] {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Sermones de communi sanctorum}}\plain \f1\lang1033\fs24 . (76\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Sermones provincialis \plain \f1\lang1033\fs24 [Franciae]\plain \f1\i\lang1033\fs24  de communi sanctorum\plain \f1\lang1033\fs24 \u8249 \'8b. (76\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) (1.) \u8250 \'9b\plain \f1\i\lang1033\fs24 De apostolis\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Qui sunt ... (Is 60,8). Principatus apostolorum volatui nubium et columbarum merito comparantur}}\plain \f1\lang1033\fs24  ...; (82\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) (19.) \u8250 \'9b\plain \f1\i\lang1033\fs24 De una virgine\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Despondi vos ... (II Cor 11,2). Desponsata Christo debet esse pulchra anima vel virgo, ut vir in eius intuitu delectetur}}\plain \f1\lang1033\fs24  ... Bestand nach Schneyer 4, S. 752-755 Nr 462. 464. 466. 467. 469. 473. 475-477. 480-482. 487. 492 (Anfang) + 494. 496. 499. 501. 506. 503. Gegen\u252 \'fcber der vollst\u228 \'e4ndigen Predigtreihe in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Theol. lat. oct. 158}}\plain \f1\lang1033\fs24 , 33\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -50\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24  der Text meist verk\u252 \'fcrzt. Text\u252 \'fcberlieferung: Kaeppeli, Scriptores OP, Nr 3326 (ohne diese Hs).
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

