\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 89\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -91\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24  [\plain \f1\scaps\lang1033\fs24 Versus {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 memoriales}}\plain \f1\scaps\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 de quattuor libris sententiarum}}\plain \f1\scaps\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Petri Lombardi}}\plain \f1\lang1033\fs24 ]. Lehrhafte, im Aufbau weitgehend an die Sentenzen des Petrus Lombardus angelehnte Dichtung, darunter mehrere mnemotechnische Verse: alle Nummern nach Walther, Initia.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (89\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Incipit prologus operis subsequentis\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 De scriptis plura que doctores reserarunt / Hec licet obscura breviter tibi metra sonarunt}}\plain \f1\i\lang1033\fs24  / Que multi cura memorandi fine pararunt.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (89\plain \f1\super\lang1033\fs24 ra-rb\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Incipit liber primus et primo de trinitate personarum et quattuor modis cognoscendi deum\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Personis trinus deus est unus deitate}}\plain \f1\lang1033\fs24  / ...; (89\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Quod simpliciter de deo senciendum est\plain \f1\lang1033\fs24 \u8249 \'8b. Nr 16253. (89\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De passione Christi et horis laicorum\plain \f1\lang1033\fs24 \u8249 \'8b. Nr 18565. Folgt: Nr 8988 (7 Verse) = [{\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Hildebertus Lavardinensis}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Carmen}}\plain \f1\lang1033\fs24 ]. Ed.: Hildeberti Cenomannensis episcopi carmina minora recensuit A. Brian Scott, Leipzig 1969, S. 54 Nr 57. (89\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 -90\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Liber secundus. De creatione rerum\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 A celum terram lucem dat, B quoque firmum}}\plain \f1\lang1033\fs24  / ...; (89\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De statu primi hominis et nostro secundum corpus\plain \f1\lang1033\fs24 \u8249 \'8b. Nr 3083. (89\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De vii viciis principalibus et eorum speciebus\plain \f1\lang1033\fs24 \u8249 \'8b. Nr 10532. (90\plain \f1\super\lang1033\fs24 ra-va\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Liber tercius. De virtutibus cardinalibus\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Iustus, temperies (recte: temperans), fortis, prudens simul esto}}\plain \f1\lang1033\fs24  / ...; (90\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De operibus misericordie et correptione fraterna\plain \f1\lang1033\fs24 \u8249 \'8b. Nr 20647. \u8250 \'9b\plain \f1\i\lang1033\fs24 De decem preceptis et plagis Egipti\plain \f1\lang1033\fs24 \u8249 \'8b ... (90\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) Nr 17276. (90\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 -91\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Incipit liber quartus et primo de sacramentis in genere\plain \f1\lang1033\fs24 \u8249 \'8b. Nr 177. (90\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De sacramento eucharistie\plain \f1\lang1033\fs24 \u8249 \'8b. Nr 13461. (91\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) Nr 10652. (91\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De confessione\plain \f1\lang1033\fs24 \u8249 \'8b. Nr 18330. (91\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De sacramento matrimonii\plain \f1\lang1033\fs24 \u8249 \'8b ... Nr 16031. (91\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De dotibus et gloria beatorum\plain \f1\lang1033\fs24 \u8249 \'8b. Nr 10896. ...-... {\field{\*\fldinst HYPERLINK "hida://5650[4]/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Explicit hoc opus hic, da nobis te deus. Amen.}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 \par}

