\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (155\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 -158\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) [{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Sermones de sanctis}}\plain \f1\lang1033\fs24 ], Stephanus - Annuntiatio BMV. (1.) \u8250 \'9b\plain \f1\i\lang1033\fs24 De sancto Stephano\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Cum esset Stephanus ... (Act 7,55). In hiis verbis beatus Stephanus a 4 commendatur, scilicet a nomine}}\plain \f1\i\lang1033\fs24 , a spiritus sancti plenitudine\plain \f1\lang1033\fs24  ...; (2.) \u8250 \'9b\plain \f1\i\lang1033\fs24 Iohannis\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Benyamin amantissimus ... (Dt 33,12). In hiis verbis notantur 4 privilegia beati Iohannis: primum est quod virgo electus a domino}}\plain \f1\lang1033\fs24  ...; (158\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) (17.) {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Letabitur deserta ... (Is 35,1). In verbis istis predicat Ysaia virginitatem beate virginis}}\plain \f1\i\lang1033\fs24  et fructum virginitatis eius\plain \f1\lang1033\fs24  ... Bricht ab. Nachweisbar: Schneyer 5, S. 605 Nr 353 ({\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Ps.-Thomas de Aquino}}\plain \f1\lang1033\fs24 ; zu 157\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ); Schneyer 8, S. 809 Nr 144 (zu 157\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ); Schneyer 9, S. 323 Nr 24 (zu 158\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ).
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

