\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 108\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -148\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  (122\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  leer) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Exercitium monachi ordinis Carthusiensis}}\plain \f1\lang1033\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 O amantissime deus, ego infelix peccator confiteor me nimis offendisse}}\plain \f1\lang1033\fs24  ...-... \plain \f1\i\lang1033\fs24 ne forte absque corde incidam in mortis discrimen. Finis hic huius exercicii.\plain \f1\lang1033\fs24  Gegliedert in 7 Teile: (108\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6922/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Confessio}}\plain \f1\lang1033\fs24  mit 12 Christus-Gebeten, am Rand gez\u228 \'e4hlt; (113\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 de beneficiis\plain \f1\lang1033\fs24 ; (123\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 de beneficiis in speciali\plain \f1\lang1033\fs24 ; (128\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 de humiliacione sui ipsiu\plain \f1\lang1033\fs24 s; (131\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 de impetracione gracie\plain \f1\lang1033\fs24 , u.a. (132\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Orationes pro vivis et defunctis; (140\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Sexta pars.\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Gebete zu Maria}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6922/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Christus}}\plain \f1\lang1033\fs24  und Heiligen; in Suffragien sollen angerufen werden: {\field{\*\fldinst HYPERLINK "hida://bezwrk[4].6922/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Schutzengel}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Iohannes Bapt.}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Andreas}}\plain \f1\lang1033\fs24  als Eigenapostel, {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Hieronymus}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezper[4].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Hu}}{\field{\*\fldinst HYPERLINK "hida://bezper[8].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 go}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezper[3].4100gi/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Aegidius}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezper[5].4100gi/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Catharina}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezper[6].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Barbara}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezper[7].4100gi/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Maria Magdalena}}\plain \f1\lang1033\fs24 , vgl. 162\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ff.; (143\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 pro caritatis donacione.\plain \f1\lang1033\fs24  Zitiert werden \plain \f1\i\lang1033\fs24 Mechtildis: Revelationes\plain \f1\lang1033\fs24  und Johannes Tauler; einige Gebete Augustinus zugeschrieben.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

