\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 173\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -176\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Orationes pro defunctis}}\plain \f1\lang1033\fs24 . (173\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 )\plain \f1\i\lang1033\fs24  Pro parentibus.\plain \f1\lang1033\fs24  CO Nr 1903. \plain \f1\i\lang1033\fs24 Pro consagwineis\plain \f1\lang1033\fs24  (!) \plain \f1\i\lang1033\fs24 et amicis.\plain \f1\lang1033\fs24  Nr 3116, nur Anfang. \plain \f1\i\lang1033\fs24 Pro familiaribus et confraternitate.\plain \f1\lang1033\fs24  Nr 1141, nur Anfang. \plain \f1\i\lang1033\fs24 Pro elemosinariis et benefactoribus.\plain \f1\lang1033\fs24  Nr 1178. (174\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Pro episcopis et sacerdotibus.\plain \f1\lang1033\fs24  Nr 1757 (Variante), am Schlu\u223 \'df unvollst\u228 \'e4ndig. \plain \f1\i\lang1033\fs24 Pro sacerdotibus.\plain \f1\lang1033\fs24  Nr 913, nur Anfang. \plain \f1\i\lang1033\fs24 Pro uno sacerdote.\plain \f1\lang1033\fs24  Nr 729; auch 175\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  (Plural). \plain \f1\i\lang1033\fs24 Pro famulo noviter defuncto.\plain \f1\lang1033\fs24  Nr 4846. \plain \f1\i\lang1033\fs24 Pro famula.\plain \f1\lang1033\fs24  Nr 4843, nur Anfang. \plain \f1\i\lang1033\fs24 Pro anniversario.\plain \f1\lang1033\fs24  Nr 1251, nur Anfang. \plain \f1\i\lang1033\fs24 Pro constructoribus nostris.\plain \f1\lang1033\fs24  Nr 4701. (174\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Pro sepultis in cimiterio.\plain \f1\lang1033\fs24  Nr 1170. \plain \f1\i\lang1033\fs24 Generalis pro omnibus.\plain \f1\lang1033\fs24  Nr 16. (175\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Pro recenti defuncto.\plain \f1\lang1033\fs24  Nr 172b (mit Abweichungen). \plain \f1\i\lang1033\fs24 Qui sine confessione moriuntur.\plain \f1\lang1033\fs24  Nr 3744. \plain \f1\i\lang1033\fs24 Pro uno episcopo.\plain \f1\lang1033\fs24  Nr 4425. \plain \f1\i\lang1033\fs24 Pro presbyteris.\plain \f1\lang1033\fs24  Nr 5780 (adaptiert). \plain \f1\i\lang1033\fs24 Pro omni clero.\plain \f1\lang1033\fs24  Nr 729; auch 174\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  (Singular). (175\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) leer. (176\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Pro nuper defuncto oracio. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Per amorem qui te dignissimum, innocentissimum et delicatissimum paterne caritatis filium}}\plain \f1\lang1033\fs24  ...; (176\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Item pro nuper defuncto oracio.{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7  In unione ferventissimi amoris illius, qui te vitam omnium vivencium coegit incarnari}}\plain \f1\lang1033\fs24  ... Beide Gebete auch Hs {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Berlin, SB, Lat. oct. 341}}\plain \f1\lang1033\fs24 , 89\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -90\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  (mit kleinen Abweichungen); vgl. auch Hs {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Darmstadt, LuHB, Hs 964}}\plain \f1\lang1033\fs24 , 128\plain \f1\super\lang1033\fs24 r-v\plain \f1\lang1033\fs24 , Kat. Darmstadt 3, S. 152 (Nr 44).
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

