\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 189\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -194\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Gaudia BMV}}\plain \f1\lang1033\fs24 . (189\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -192\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Quindecim gaudia. \plain \f1\i\lang1033\fs24 Incipiunt XV gaudia beate virginis.\plain \f1\lang1033\fs24  Text: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 O dulcissima domina nostra sancta Maria, pro ineffabili gaudio, quod de suavissima salutacione ... habuisti}}\plain \f1\lang1033\fs24  ... 15 {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Gebete}}\plain \f1\lang1033\fs24 , jeweils mit identischem Anfang, auch {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Theol. lat. oct. 137}}\plain \f1\lang1033\fs24 , 73\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -76\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 . (192\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -193\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Quinque gaudia. \plain \f1\i\lang1033\fs24 Incipiunt adhuc alie quinque gaudio\plain \f1\lang1033\fs24  (!) \plain \f1\i\lang1033\fs24 de beate virgine.\plain \f1\lang1033\fs24  Text: {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 O sanctissima dei genitrix et perpetua virgo Maria, saluto te}}\plain \f1\lang1033\fs24  ..., \plain \f1\i\lang1033\fs24 O nobilissima\plain \f1\lang1033\fs24  ..., \plain \f1\i\lang1033\fs24 O speciosissima\plain \f1\lang1033\fs24  ..., \plain \f1\i\lang1033\fs24 O pulcherrima\plain \f1\lang1033\fs24  ..., \plain \f1\i\lang1033\fs24 O beatissima\plain \f1\lang1033\fs24  ..., schlie\u223 \'dft mit: \plain \f1\i\lang1033\fs24 O misericordissima\plain \f1\lang1033\fs24  ... \plain \f1\i\lang1033\fs24 super omnia saluto te\plain \f1\lang1033\fs24  ... Zwischen 192\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  u. 193\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  kein Textverlust. Auch Hs {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Berlin, SB, Lat. oct. 404}}\plain \f1\lang1033\fs24 , 50\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -51\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , dort die beiden letzten Gr\u252 \'fc\u223 \'dfe in einem Abschnitt zusammengefa\u223 \'dft. (193\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -194\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Septem gaudia. \plain \f1\i\lang1033\fs24 Incipiunt alia septem gaudia beate virginis.\plain \f1\lang1033\fs24  AH 31, Nr 193.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

