\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 194\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -196\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \plain \f1\scaps\lang1033\fs24 15 {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Passionsermahnungen}}\plain \f1\lang1033\fs24 , dt. \plain \f1\i\lang1033\fs24 Incipiunt XV ammoniciones.\plain \f1\lang1033\fs24  Text: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Ich ermane dich here Ihesu Christe der czudenunge aller dyner gelyddemaszen}}\plain \f1\lang1033\fs24  ...-... \plain \f1\i\lang1033\fs24 das helfft myr dy gotiskrafft vnde aller heyligen meynschafft. Amen.\plain \f1\lang1033\fs24  Abschlu\u223 \'df jeweils mit Pater noster. Vgl. \u228 \'e4hnliche Fassungen Hs {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Augsburg, UB, Cod. III.1.4\u176 \'b0 3}}\plain \f1\lang1033\fs24 , Nr 5c, Kat. Augsburg UB 2.1, S. 252; gleichfalls als {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Pater-noster-Gebete}}\plain \f1\lang1033\fs24  Hs {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Freiburg, Erzbisch\u246 \'f6fl. Archiv, Hs. 11}}\plain \f1\lang1033\fs24 , 89\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -95\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , Kat. Freiburg 1.4 A, S. 220.
