\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 241\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -242\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \plain \f1\scaps\lang1033\fs24 Kurze {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 mystische}}\plain \f1\scaps\lang1033\fs24  Texte\plain \f1\lang1033\fs24 , lat. u. dt. \u220 \'dcberschrift, auf \u252 \'fcberklebtem Text: \plain \f1\i\lang1033\fs24 Pro via unitiva.\plain \f1\lang1033\fs24  (241\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -242\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Exzerpte aus Hugo de Balma, lat., und Bernardus, dt., kombiniert mit 2 Gebeten, lat. u. dt.: {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 O bone domine adolescentule, quando te constringam}}\plain \f1\lang1033\fs24  ..., auch 246\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ; {\field{\*\fldinst HYPERLINK "hida://5650[2].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Ach du myn allerlybestes eyniges lyb, were ich des wyrdich}}\plain \f1\lang1033\fs24  ...; (242\plain \f1\super\lang1033\fs24 r-v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Johannes Tauler}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Predigten}}\plain \f1\lang1033\fs24 , Exzerpt, dt. \plain \f1\i\lang1033\fs24 Der Tauler von der verwuntten lybe vnde gefangen lybe super illo verbo \lquote Iohannes erat lucerna lucens et ardens\rquote .\plain \f1\lang1033\fs24  Text: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Dys licht vnde hicze ist dy verwuntte lybe}}\plain \f1\lang1033\fs24  ...-... \plain \f1\i\lang1033\fs24 das ich dich lyb habe von all.\plain \f1\lang1033\fs24  Ed. cit. (wie 62\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ), S. 333 Z. 9-27.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Arial;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 242\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -243\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Der Kuttenmann}}\plain \f1\lang1033\fs24 : [{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Vom Reuer, Wirker und Schauer}}\plain \f1\lang1033\fs24 ], Exzerpt. \u220 \'dcberschrift: \plain \f1\i\lang1033\fs24 Artige rede sponse in absencia sponsi Kuthmanni.\plain \f1\lang1033\fs24  Text: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 O du grundelosze selikeit, wy gar hast du myr das hercze vmmegekart}}\plain \f1\lang1033\fs24  ...-... \plain \f1\i\lang1033\fs24 Szo salt du myr ouch vmme das mynen nichtes geben\plain \f1\lang1033\fs24  ... \plain \f1\i\lang1033\fs24 Fiat voluntas tua sicut in celo et in terra.\plain \f1\lang1033\fs24  \u220 \'dcbereinstimmend mit Hs {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Berlin, SB, Lat. oct. 214}}\plain \f1\lang1033\fs24 , 117\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 7. Z. v.u. - 118\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 8. Z. v.o., vgl. MBKD 2, S. 309 Z. 39f. Zur handschriftl. \u220 \'dcberlieferung s. Bernhard D. Haage, Lotte Kurras, in: VL\plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24  5, 1985, Sp. 472-474. S.a. oben 38\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -56\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 67\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -69\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 74\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -86\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

