\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 278\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -281\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  [{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Orationes] de passione Christi}}\plain \f1\scaps\lang1033\fs24  ad horas canonicas\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Hic incipiunt ix\plain \f1\lang1033\fs24  (!) \plain \f1\i\lang1033\fs24 graciarum acciones de passione domini devotas.\plain \f1\lang1033\fs24  Text: \plain \f1\i\lang1033\fs24 Ad vesperas. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Gracias tibi ago, benedicte domine Ihesu Christe, quia tu es salvator meus verus}}\plain \f1\i\lang1033\fs24  qui hora diei vespertina\plain \f1\lang1033\fs24  ...-... \plain \f1\i\lang1033\fs24 ad beatorum gloriam merear pervenire quod mihi prestare dignetur.\plain \f1\lang1033\fs24  7 Gebete zu Vesper, Komplet, Matutin, Prim bis Non. Auch Hs Berlin, SB, Lat. oct. 404, 208\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -210\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 .
