\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs20 Pergament unterschiedlicher Qualit\u228 \'e4t; 1\plain \f1\super\lang1033\fs20 v\plain \f0\fs20  P-Initiale ausgeschnitten, s.u.; Bl 95 in der oberen H\u228 \'e4lfte unregelm\u228 \'e4\u223 \'dfig ausgeschnittene Fehlstelle, Wortverlust; auf den letzten Seiten Wasserflecken \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  Lagen: 8 IV\plain \f1\super\lang1033\fs20 64\plain \f0\fs20  + (IV-1)\plain \f1\super\lang1033\fs20 71\plain \f0\fs20  + 3 IV\plain \f1\super\lang1033\fs20 95\plain \f0\fs20 ; vor Bl 65 1 Bl ausgeschnitten, ohne Textverlust; vor Bl 88 vermutlich 2 Lagen verloren, mit erheblichem Textverlust \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  8\plain \f1\super\lang1033\fs20 v\plain \f0\fs20 -64\plain \f1\super\lang1033\fs20 v\plain \f0\fs20  Lagenz\u228 \'e4hlung \plain \f1\i\lang1033\fs20 A-H\plain \f0\fs20 , teils mit Punktverzierung \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  Schriftraum 15-16,5 \plain \f2\lang1024\fs20 \u180 \'b4\plain \f0\fs20  8,5-9,5 \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  80\plain \f1\super\lang1033\fs20 r-v\plain \f0\fs20  2 Spalten \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  27 Zeilen \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  fr\u252 \'fche {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f0\fs20\chcbpat7 gotische Minuskel}}\plain \f0\fs20  von mehreren H\u228 \'e4nden, einer der Schreiber Rainerus, Gast im Kloster Hautmont, s.u. 64\plain \f1\super\lang1033\fs20 r\plain \f0\fs20 . 93\plain \f1\super\lang1033\fs20 r\plain \f0\fs20 ; Korrekturen \u252 \'fcber Rasuren und vereinzelt Erg\u228 \'e4nzungen auf den R\u228 \'e4ndern \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  64\plain \f1\super\lang1033\fs20 v\plain \f0\fs20  Nachtrag: {\field{\*\fldinst HYPERLINK "hida://5705[0]/?u"}{\fldrslt \plain \f0\fs20\chcbpat7 Quadratnotation}}\plain \f0\fs20  auf {\field{\*\fldinst HYPERLINK "hida://5705[1]/?u"}{\fldrslt \plain \f0\fs20\chcbpat7 4-Linien-System}}\plain \f0\fs20  \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  52\plain \f1\super\lang1033\fs20 v\plain \f0\fs20  Nota-Zeichen \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  64\plain \f1\super\lang1033\fs20 v\plain \f0\fs20  fl\u252 \'fcchtige Blindstiftzeichnung: Flechtranke (?), dar\u252 \'fcber Buchstaben (?); 37\plain \f1\super\lang1033\fs20 v\plain \f0\fs20  neuzeitliche (?) Randfigur in Tinte, verwischt \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  sparsam rubriziert, nur 1\plain \f1\super\lang1033\fs20 v\plain \f0\fs20 -32\plain \f1\super\lang1033\fs20 r\plain \f0\fs20  am Rand rote Kapitelz\u228 \'e4hlung und Autorit\u228 \'e4ten, h\u228 \'e4ufig beschnitten \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  64\plain \f1\super\lang1033\fs20 r\plain \f0\fs20 . 65\plain \f1\super\lang1033\fs20 r\plain \f0\fs20 -66\plain \f1\super\lang1033\fs20 r\plain \f0\fs20 . 74\plain \f1\super\lang1033\fs20 v\plain \f0\fs20 -75\plain \f1\super\lang1033\fs20 v\plain \f0\fs20 . 80\plain \f1\super\lang1033\fs20 ra-vb\plain \f0\fs20 . 86\plain \f1\super\lang1033\fs20 v\plain \f0\fs20 -87\plain \f1\super\lang1033\fs20 v\plain \f0\fs20 . 89\plain \f1\super\lang1033\fs20 r-v\plain \f0\fs20  rote und gr\u252 \'fcne Satzmajuskeln f\u252 \'fcr Verse \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  1\plain \f1\super\lang1033\fs20 v\plain \f0\fs20 . 16\plain \f1\super\lang1033\fs20 r\plain \f0\fs20 . 37\plain \f1\super\lang1033\fs20 r\plain \f0\fs20 . 69\plain \f1\super\lang1033\fs20 r\plain \f0\fs20  u.\u246 \'f6. 2- bis 6zeilige gr\u252 \'fcne, blaue, rote und braune {\field{\*\fldinst HYPERLINK "hida://5270[0]/?u"}{\fldrslt \plain \f0\fs20\chcbpat7 Silhouetteninitialen}}\plain \f0\fs20  mit einfachem Bogendekor zu den Buch- bzw. Kapitelanf\u228 \'e4ngen \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  66\plain \f1\super\lang1033\fs20 r\plain \f0\fs20  6zeilige goldene {\field{\*\fldinst HYPERLINK "hida://5270[1]/?u"}{\fldrslt \plain \f0\fs20\chcbpat7 Rankeninitiale}}\plain \f0\fs20  auf farbigem Grund, in den Ranken ein kletternder roter Vierbeiner (L\u246 \'f6we) \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  1\plain \f1\super\lang1033\fs20 v\plain \f0\fs20  ausgeschnitten: Eingangsinitiale, 5zeilig, Schaft mit langem Ausl\u228 \'e4ufer entlang des Schriftspiegels.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Arial;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs20 Die Hs wurde in der Benediktinerabtei Hautmont (D\u233 \'e9partement Nord; Hennegau) von mehreren Schreibern geschrieben; darunter {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100gi/?u"}{\fldrslt \plain \f0\fs20\chcbpat7 Rainerus}}\plain \f0\fs20  aus Liessies, dessen Namen man aus dem Akrostichon-Telostichon (64\plain \f1\super\lang1033\fs20 r\plain \f0\fs20 ) erf\u228 \'e4hrt und der in einem Gedicht (93\plain \f1\super\lang1033\fs20 r\plain \f0\fs20 ) als Gast des Klosters bezeichnet wird. Er ist m\u246 \'f6glicherweise identisch mit jenem Schreiber gleichen Namens (Rainerus aus Saint-Ghislain bzw. Rainerus Cellensis), der w\u228 \'e4hrend des letzten Viertels des 12. Jhs in Hautmont an weiteren Handschriften mitgearbeitet hat: Hss {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f0\fs20\chcbpat7 Paris, BN, Nouv. acq. lat. 264}}\plain \f0\fs20  u. {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f0\fs20\chcbpat7 1543}}\plain \f0\fs20 ; vgl. Leclercq, Hautmont, aaO., S. 65f.; CMD-F IV/1, S. 63, 189 u. Taf. 26, 28. Die Lokalisierung und Datierung wird auch durch den Initialstil best\u228 \'e4tigt, s. Andreas Fingernagel, in: Kat. Berlin Illum. 2, S. 92f. \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  aus dem Besitz des Historikers {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100gi/?u"}{\fldrslt \plain \f0\fs20\chcbpat7 Isidore Gabriel Joseph Lebeau}}\plain \f0\fs20  (*1767, \u8224 \'86 1831; Archives biographiques fran\u231 \'e7aises, Fiche I 617, 358) an {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100gi/?u"}{\fldrslt \plain \f0\fs20\chcbpat7 Adrien-Joseph Michaux a\u238 \'een\u233 \'e9}}\plain \f0\fs20  (*1801, \u8224 \'861876), Pr\u228 \'e4sident der Soci\u233 \'e9t\u233 \'e9 Arch\u233 \'e9ologique d\rquote Avesnes; die in einem Doppelkreis auf dem Verso des zweiten Vorsatzbls vermerkte Z\u228 \'e4hlung: \plain \f1\i\lang1033\fs20 N\plain \f1\i\super\lang1033\fs20 o\plain \f1\i\lang1033\fs20 . 2\plain \f0\fs20  d\u252 \'fcrfte sich auf den f\u252 \'fcr den Verkauf erstellten handschriftl. Katalog der Sammlung Lebeaus beziehen, s. Einleitung \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  {\field{\*\fldinst HYPERLINK "hida://bezsoz[0].4996/?u"}{\fldrslt \plain \f0\fs20\chcbpat7 1851}}\plain \f0\fs20  zusammen mit {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f0\fs20\chcbpat7 Theol. lat. fol. 451}}\plain \f0\fs20 , {\field{\*\fldinst HYPERLINK "hida://5007[3].501m/?u"}{\fldrslt \plain \f0\fs20\chcbpat7 Lat. fol. 358-360}}\plain \f0\fs20  und \plain \f0\fs20\chcbpat7  {\field{\*\fldinst HYPERLINK "hida://5007[4].501m/?u"}{\fldrslt \plain \f0\fs20\chcbpat7 Theol. lat. oct. 94}}\plain \f0\fs20  von \ldblquote Michaux a\u238 \'een\u233 \'e9, \u224 \'e0 Avesnes\rdblquote  an die K\u246 \'f6nigl. Bibliothek verkauft \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  auf dem zweiten Vorsatzbl verso Papierzettel mit eigenh\u228 \'e4ndiger Notiz von \plain \f1\i\lang1033\fs20 H. Ostlender, 1924\plain \f0\fs20 , \u252 \'fcber die Identifizierung des Abaelard-Textes eingeklebt \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  Akz.Nr {\field{\*\fldinst HYPERLINK "hida://bezsoz[0].4656/?u"}{\fldrslt \plain \f0\fs20\chcbpat7 3631}}\plain \f0\fs20 , vielleicht bei der Neubindung mit dem Spiegelbl entfernt.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

