\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 253\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -313\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 [Casus] Summarii}}\plain \f1\scaps\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Libri Sexti}}\plain \f1\scaps\lang1033\fs24  [decretalium {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Bonifatii VIII.}}\plain \f1\lang1033\fs24 ]. (253\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Bonifacius episcopus etc. Per benediccionem pape prelatis devote susceptam venialia remittuntur}}\plain \f1\i\lang1033\fs24 , hec glosa. Sacrosancte. Divina providencia voluit ecclesiam Romanam pre aliis ecclesiis optinere principatum\plain \f1\lang1033\fs24  ... Liber I: \u8250 \'9b\plain \f1\i\lang1033\fs24 De summa trinitate\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Fideli ac devota}}\plain \f1\lang1033\fs24\chcbpat7  (VI 1.1.1). {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Spiritus sanctus eternaliter a patre et filio tamquam ex uno principio et una spiratione procedit}}\plain \f1\lang1033\fs24  ... Liber II: (278\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Liber 2\plain \f1\i\super\lang1033\fs24 us\plain \f1\i\lang1033\fs24  de iudiciis\plain \f1\lang1033\fs24 \u8249 \'8b. \plain \f1\i\lang1033\fs24 Iuris esse ambiguum\plain \f1\lang1033\fs24  (VI 2.1.1). \plain \f1\i\lang1033\fs24 Iudex delegatus, non habens ad hoc speciale mandatum a papa, non potest compellere partes, ut personaliter coram eo compareant, nisi causa fuerit criminalis\plain \f1\lang1033\fs24  ... Liber III: (283\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Liber 3\plain \f1\i\super\lang1033\fs24 us\plain \f1\i\lang1033\fs24  de vita et honestate clericorum\plain \f1\lang1033\fs24 \u8249 \'8b. \plain \f1\i\lang1033\fs24 Clerici qui\plain \f1\lang1033\fs24  (VI 3.1.1). \plain \f1\i\lang1033\fs24 Clericus ioculator vel scurro 2\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  vel 3\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  monitus non desistens ipso iure perdit privilegium clericale\plain \f1\lang1033\fs24  ... Liber IV: (297\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Incipit liber iiii\plain \f1\i\super\lang1033\fs24 us\plain \f1\i\lang1033\fs24  de sponsalibus et matrimonio\plain \f1\lang1033\fs24 \u8249 \'8b. \plain \f1\i\lang1033\fs24 Ex sponsalibus certis\plain \f1\lang1033\fs24  (VI 4.1.1). \plain \f1\i\lang1033\fs24 Si quis contraxit sponsalia cum certa et nomitata \plain \f1\lang1033\fs24 (!)\plain \f1\i\lang1033\fs24  persona et pure quamvis sint nulla racione consanguinitatis vel affinitatis\plain \f1\lang1033\fs24  ... Liber V: (298\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Incipit liber 5\plain \f1\i\super\lang1033\fs24 us\plain \f1\i\lang1033\fs24  de accusacionibus, inquisicionibus et denunciacionibus\plain \f1\lang1033\fs24 \u8249 \'8b. \plain \f1\i\lang1033\fs24 Postquam\plain \f1\lang1033\fs24  (VI 5.1.1). \plain \f1\i\lang1033\fs24 Confessus crimina in inquisicione confessionem suam impugnare non potest\plain \f1\lang1033\fs24  ... (310\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Sicud nobis\plain \f1\lang1033\fs24  (VI 5.12.5). \plain \f1\i\lang1033\fs24 Privilegiato aliquo ut possit conferre beneficia suorum clericorum\plain \f1\lang1033\fs24  ... \u8250 \'9b\plain \f1\i\lang1033\fs24 De regulis iuris\plain \f1\lang1033\fs24 \u8249 \'8b. \plain \f1\i\lang1033\fs24 Beneficium ecclesiasticum\plain \f1\lang1033\fs24  (regula 1-88) ...- (313\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) ... {\field{\*\fldinst HYPERLINK "hida://5650[2]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Datum Rome apud sanctum Petrum va Nonas Marcii, pontificatus nostri anno iiii. Amen. \u8250 \'9bExpliciunt summarii libri vi\u8249 \'8b.}}\plain \f1\lang1033\fs24  Zitiert werden: (253\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  u.\u246 \'f6.) \plain \f1\i\lang1033\fs24 glosa\plain \f1\lang1033\fs24 , (253\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Jo.An.\plain \f1\lang1033\fs24  ({\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Johannes Andreae}}\plain \f1\lang1033\fs24 ), (255\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 ut ff\plain \f1\lang1033\fs24  (Digesten). H\u228 \'e4ufig enge bis w\u246 \'f6rtliche \u220 \'dcbereinstimmung mit Hss {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Berlin, SB, Lat. fol. 167}}\plain \f1\lang1033\fs24 , 38\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -56\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  (Rose 2.2 Nr 673) und {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Lat. qu. 209}}\plain \f1\lang1033\fs24 , 95\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -109\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24  (Rose 2.2 Nr 674); vgl. Schulte, Geschichte 2, S. 505 mit Anm. 4.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

