\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 313\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -327\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 [Casus] summarii}}\plain \f1\scaps\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Clementinarum}}\plain \f1\lang1033\fs24 . (313\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Incipiunt clementine\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Iohannes episcopus etc. Prohemium huius libri quatuor habet partes}}\plain \f1\i\lang1033\fs24 . Primo componit salutacionem cum benediccione \plain \f1\lang1033\fs24 ... Liber I: \u8250 \'9b\plain \f1\i\lang1033\fs24 De summa trinitate et fide katholica\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Fidei katholice (Clem. 1.1.1). Quatuor partes ponit, primo ostendit de humane carnis Christi assumpcione}}\plain \f1\lang1033\fs24  ... Liber II: (316\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Incipit liber 2\plain \f1\i\super\lang1033\fs24 us\plain \f1\i\lang1033\fs24  de iudiciis\plain \f1\lang1033\fs24 \u8249 \'8b. \plain \f1\i\lang1033\fs24 Dudum\plain \f1\lang1033\fs24  (Clem. 2.1.1). \plain \f1\i\lang1033\fs24 Citacio facta in publica audiencia de speciali mandato pape illos artat, qui impediunt\plain \f1\lang1033\fs24  ... Liber III: (318\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Incipit liber tercius de vita et honestate clericorum\plain \f1\lang1033\fs24 \u8249 \'8b. (319\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Dyocesanis\plain \f1\lang1033\fs24  (Clem. 3.1.1). \plain \f1\i\lang1033\fs24 Clerici officium carnificum vel alia negocia secularia hoc \plain \f1\lang1033\fs24 (!)\plain \f1\i\lang1033\fs24  prohibita exercentes ter moniti non desistentes\plain \f1\lang1033\fs24  ... \plain \f1\i\lang1033\fs24 si coniugati sunt, perdunt totum privilegium clericale\plain \f1\lang1033\fs24  ... Liber IV: (324\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Liber 4\plain \f1\i\super\lang1033\fs24 us\plain \f1\i\lang1033\fs24  de consanguinitate et affinitate\plain \f1\lang1033\fs24 \u8249 \'8b. \plain \f1\i\lang1033\fs24 Eos qui\plain \f1\lang1033\fs24  (Clem. 4.1.1). \plain \f1\i\lang1033\fs24 Contrahens scienter in gradu prohibito aut cum mortali \plain \f1\lang1033\fs24 (!)\plain \f1\i\lang1033\fs24  vel prohibitus religione vel ordine est excommunicatus ipso facto.\plain \f1\lang1033\fs24  Liber V: \u8250 \'9b\plain \f1\i\lang1033\fs24 Liber 5\plain \f1\i\super\lang1033\fs24 us\plain \f1\i\lang1033\fs24  de magistris\plain \f1\lang1033\fs24 \u8249 \'8b. \plain \f1\i\lang1033\fs24 Inter\plain \f1\lang1033\fs24  (Clem. 5.1.1). \plain \f1\i\lang1033\fs24 In studiis Romane curie, Parysiensi, Oxoniensi, Bononiensi et Solomitana\plain \f1\lang1033\fs24  (!) \plain \f1\i\lang1033\fs24 debent esse magistri periti in linguis arabice, hebraice et caldee\plain \f1\lang1033\fs24  ...- (327\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) ...\plain \f1\i\lang1033\fs24  si in talibus ordo iuris fuerit observatus, non reprobatur\plain \f1\lang1033\fs24  ... \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[2]/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Expliciunt summarii clementinarum anno domini M\u176 \'b0 c\u176 \'b0c\u176 \'b0c\u176 \'b0 xciiii in die sancti Iohannis ante portam latinam (6.5.) et cetera}}\plain \f1\lang1033\fs24 \u8249 \'8b. Zahlreiche \u220 \'dcbereinstimmungen mit Hs {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Berlin, SB, Lat. qu. 209}}\plain \f1\lang1033\fs24 , 110\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -113\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  (Rose 2.2 Nr 674); vgl. Schulte, Geschichte 2, S. 506 mit Anm. 1.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

