\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 26\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -28\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Mariengruss}}\plain \f1\lang1033\fs24 , dt. \u8250 \'9b\plain \f1\i\lang1033\fs24 Oratio devota de domina ante communionem. Ave Maria\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 O Maria, bluende rosa an dorn, mit mynen sunden gro\u223 \'df hon ich dyn liebes kint verloren}}\plain \f1\lang1033\fs24  ...-... \plain \f1\i\lang1033\fs24 das du myr sie, liebe Maria, also rechte wolbewar von deme leidigen viende gar. Amen.\plain \f1\lang1033\fs24  7 Abschnitte, eingeleitet durch \u8250 \'9b\plain \f1\i\lang1033\fs24 Ave Maria\plain \f1\lang1033\fs24 \u8249 \'8b. Variante zu: Wackernagel, Kirchenlied 2, Nr 60, Str. 3. 1. 2. 4-6 (3. Strophe ohne Entsprechung). Zur \u220 \'dcberlieferung: Peter Appelhans, Untersuchungen zur sp\u228 \'e4tmittelalterlichen Mariendichtung. Die rhythmischen mittelhochdeutschen Mariengr\u252 \'fc\u223 \'dfe (Germanische Bibliothek. Dritte Reihe Untersuchungen), Heidelberg 1970, Nr 2; vgl. Burghart Wachinger, in: VL\plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24  6, 1987, Sp. 3f.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

