\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 28\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -34\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Gratiarum actio}}\plain \f1\scaps\lang1033\fs24  [post missam]\plain \f1\lang1033\fs24 . \u8250 \'9b\plain \f1\i\lang1033\fs24 Sequuntur modo actiones graciarum\plain \f1\lang1033\fs24 \u8249 \'8b. \u196 \'c4hnlich einem Recessus altaris: Benedicite. Ps 116. 145. 150. Nunc dimittis. Te deum, jeweils nur Anf\u228 \'e4nge, gerahmt von der Antiphon: CAO Nr 5191. Kyrie. Pater noster. Versikel. Orationen: (28\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -29\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Gracias tibi ago, clementissime mundi redemptor, Christe}}\plain \f1\i\lang1033\fs24 , qui\plain \f1\lang1033\fs24  ... Vgl. Leroquais, Livres d\rquote heures 2, S. 133. (29\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -30\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) CO Nr 2136. 74. 3377. 4788. (30\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -34\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) 4 Eya-Gebete: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Eya deus meus, misericordia mea, parce michi misere peccatrici}}\plain \f1\lang1033\fs24  ...; (31\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) [Eya] {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Gracias tibi ago, dulcissime deus, quia me ad tuum ministerium elegisti}}\plain \f1\lang1033\fs24  ...; (32\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Eya, nunc, domine, oro, ut sit michi, pijssime deus, hoc dulcissimum sacramentum ... medicamentum}}\plain \f1\lang1033\fs24  ...; (33\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Eya precor eciam te, pijssime deus, pro N., ut per huius adiutricem sacramenti}}\plain \f1\lang1033\fs24  ... Druck, mit Abweichungen: Klapper, Schriften Johanns von Neumarkt, S. 266-271 Nr 71,1-4 (1-3 lat., 4 nur dt.). Vgl. auch Hs {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 L\u252 \'fcneburg, RatsB, Ms. Theol. 4\u176 \'b0 54}}\plain \f1\lang1033\fs24 , 35\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -36\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , Kat. L\u252 \'fcneburg 3, S. 85.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

