\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 34\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -40\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \plain \f1\scaps\lang1033\fs24 6 {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Pater-noster-Gebete}}\plain \f1\lang1033\fs24 , dt. (34\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Dit sint v Pater noster, die man sail beden un\u223 \'dfer frauwen lyden als hie geschreben steit, das seste un\u223 \'dferm herren, veir sie bit\plain \f1\lang1033\fs24  (!) \plain \f1\i\lang1033\fs24 andacht be\plain \f1\lang1033\fs24 (34\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 )\plain \f1\i\lang1033\fs24 det, dem enwil got kyene bede versan, die em nutze ist, das hat hee siner muder gelobet\plain \f1\lang1033\fs24  ... \plain \f1\i\lang1033\fs24 Oratio\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 O Maria, muder der barmherczichkeit, ich manen dich des g[r]undelosen herczeleides, des du hette, da du sege dyn kynt das cruce off syme halse dren}}\plain \f1\lang1033\fs24  ...; (35\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 O Maria, muder der barmherczekeit, ich manen dich des iemerlichen gangis, des dyn liebis kynt vorba\u223 \'df ging}}\plain \f1\lang1033\fs24  ...; (39\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 O herre Ihesu Christe, ich manen dich des gro\u223 \'dfen herczenleides, des du hette von den betrupten elendi(40r)gen fu\u223 \'dfdrappen, die dir dyn muder Maria nach ging}}\plain \f1\lang1033\fs24  ...- (40\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) ... \plain \f1\i\lang1033\fs24 die mir erwerbe alles das mir nucze sie. Amen.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 \par}

