\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 41\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -62\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Passionspsalter}}\plain \f1\lang1033\fs24 . (41\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Oratio de passione domini\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Domine Ihesu Christe, imploro te per sanctos accessus quibus ad crucem accessisti}}\plain \f1\i\lang1033\fs24  et per sanguineum sudorem et per timorem\plain \f1\lang1033\fs24  ... Es folgen Ps 21-30,6 mit den Antiphonen: CAO Nr 4395. 1442. 4045. 2444. 3736. 4095. 5187. 1512. 3537. 4343. Responsorium: CAO Nr 7760 mit Versus B. (58\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Magnificat. \u8250 \'9b\plain \f1\i\lang1033\fs24 Antiphona\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Alpha et o, omnium salus et virtus, ad te dirigimus}}\plain \f1\lang1033\fs24  ... Auch Hs {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Stuttgart, LB, HB I 69}}\plain \f1\lang1033\fs24 , 105\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , Kat. Stuttgart HB 1.1, S. 112. (59\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Antiphona}}\plain \f1\lang1033\fs24 \u8249 \'8b. Salve regina. Orationen: (60\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) CO Nr 2032. (62\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) CO Nr 3178a. Weitere Initien im Register.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

