\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 101\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -114\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Psalterandacht}}\plain \f1\scaps\lang1033\fs24  zu {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100gi/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Maria}}\plain \f1\scaps\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100gi/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Joachim}}\plain \f1\scaps\lang1033\fs24  und {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100gi/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Anna}}\plain \f1\lang1033\fs24 . (101\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Si quis est in aliqua necescitate \plain \f1\lang1033\fs24 (!)\plain \f1\i\lang1033\fs24  vel angustia, decantet hoc psalterium in honore sancte Marie et Ioachim et sancte Anne ante altare\plain \f1\lang1033\fs24  (101\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 pro ymagine beate Marie virginis et cottidie septem psalmos lege\plain \f1\lang1033\fs24  ...\u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Salve sancta parens matris Christi, Anna, ferens mundo Christi pacem cum leticia}}\plain \f1\lang1033\fs24  ... (102\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Ps 84 (nur Anfang). {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Oratio}}\plain \f1\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Quia parentes tui, o Maria, de quibus tu virgo ... processisti}}\plain \f1\lang1033\fs24  ... (102\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Magnificat. \u8250 \'9b\plain \f1\i\lang1033\fs24 Ave Maria\plain \f1\lang1033\fs24 \u8249 \'8b. Oratio: {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 O Maria, mater dei, ad cuius nomen respirant rei}}\plain \f1\lang1033\fs24  ... Es folgen Gruppen von Gebeten, darunter: (107\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) CO Nr 1366a. (107\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Nr 4145; (108\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Nr 3809 (Variante); (113\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Nr 3134; weitere Initien im Register; im Wechsel mit Psalmen: (105\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Ps 1. (108\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Ps 129. 32 oder 80. (113\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -114\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Ps 1. 8. 15. 22. 29. 36. 43. 50. 57. 64. 71. 78. 85. 92. 99. 104 oder 105. 113. 120. 127. 134. 141. 148-150 (jeweils nur Anf\u228 \'e4nge). Schlie\u223 \'dft (114\plain \f1\super\lang1033\fs24 r-v\plain \f1\lang1033\fs24 ) mit Miserere mei. Benedicite. Te deum. Magnificat (nur Anf\u228 \'e4nge).
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Arial;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 114\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -130\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Orationes de adventu Christi}}\plain \f1\lang1033\fs24 . (114\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Incipit oracio de desiderabilissimo adventu domini nostri Ihesu Christi\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Gloria tibi, inperialissima trinitas, pro desiderio, quod eternaliter ab omni afflictione habuisti}}\plain \f1\lang1033\fs24  ... (115\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -121\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Gebete an die Trinit\u228 \'e4t, die 3 g\u246 \'f6ttlichen Personen (mit Bitte an Maria) und zu Maria. (121\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -129\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) 7 Gebete zu Christus, dazwischen O-{\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Antiphonen}}\plain \f1\lang1033\fs24 : CAO Nr 4081. 3988. 4075. 4010. 4050. 4078. Initien im Register. Schlie\u223 \'dft (129\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) mit Antiphon: CAO Nr 5321. \u8250 \'9b\plain \f1\i\lang1033\fs24 Oracio\plain \f1\lang1033\fs24 \u8249 \'8b. CO Nr 2550.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Arial;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 130\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -170\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Gebete zur Vorbereitung und beim Empfang der Kommunion}}\plain \f1\lang1033\fs24 . (130\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -151\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Zur Vorbereitung: (130\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Einleitung: {\field{\*\fldinst HYPERLINK "hida://5650[35].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 O inclita filia Syon, pensa et considera, quanta reverencia et diligencia ac quali virtutum ornatu thalamum anime tue preparare debeas}}\plain \f1\i\lang1033\fs24  septem diebus\plain \f1\lang1033\fs24  ...- (131\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 dicens hanc oracionem.\plain \f1\lang1033\fs24  \u8250 \'9b\plain \f1\i\lang1033\fs24 Oracio\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Domine Ihesu Christe, fili dei vivi, qui dixisti: Sine me nichil potestis facere}}\plain \f1\lang1033\fs24  ... (131\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Psalmus\plain \f1\lang1033\fs24 \u8249 \'8b. Ps 69 (nur Anfang). \u8250 \'9b\plain \f1\i\lang1033\fs24 Hunc psalmum et prescriptam oracionem coctidie \plain \f1\lang1033\fs24 (!)\plain \f1\i\lang1033\fs24  in mane dicas cum devocione illis diebus, quando te preparas ad suscepcionem corpus \plain \f1\lang1033\fs24 (!)\plain \f1\i\lang1033\fs24  Christi, in prima diligenter vitam tuam examina\plain \f1\lang1033\fs24  ...- (132\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) ... \plain \f1\i\lang1033\fs24 et dic psalmum\plain \f1\lang1033\fs24 \u8249 \'8b. Ps 24 (nur Anfang). \u8250 \'9b\plain \f1\i\lang1033\fs24 Post psalmum dic sequentem oracionem\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[14].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Domine Ihesu Christe, per misericordiam, qua divinum cor tuum liquefactum est}}\plain \f1\lang1033\fs24  ... \u8250 \'9b\plain \f1\i\lang1033\fs24 Pater noster\plain \f1\lang1033\fs24 \u8249 \'8b. Es folgen f\u252 \'fcr die einzelnen Tage eine l\u228 \'e4ngere rubrizierte Anweisung, ein Psalm (12. 21. 53. 66. 140. 141, nur Anf\u228 \'e4nge) und je 3 Gebete, Initien im Register.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (151\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -170\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Zu Kommunion: \u8250 \'9b\plain \f1\i\lang1033\fs24 Ante communionem dicas sequentes oraciones\plain \f1\lang1033\fs24 \u8249 \'8b. (1.) {\field{\*\fldinst HYPERLINK "hida://5650[32].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 O anima, nobilis creatura, (152r) erige nunc totum intellectum tuum et attende}}\plain \f1\lang1033\fs24  ...; (152\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) (2.) {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Creator omnium rerum, deus pater omnipotens, cuius principium inicium non recipit}}\plain \f1\lang1033\fs24  ...; (153\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) (3.) \u8250 \'9b\plain \f1\i\lang1033\fs24 Alia oracio\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[30].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 O anima mea, recollige omnes vires et affectiones tuos et postula}}\plain \f1\lang1033\fs24  ...; (154\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) (4.) \u8250 \'9b\plain \f1\i\lang1033\fs24 Alia oracio\plain \f1\lang1033\fs24 \u8249 \'8b. (154\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[41].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Veni, sancte spiritus, victor invincibilis, nostra victus miseria, cape nos aureis cathenis}}\plain \f1\lang1033\fs24  ... Nr 2 u. 4 = Teil 1 u. 6 aus dem Gebet \ldblquote Carthusia\rdblquote ; vgl. G. Meyer, in: Kat. Basel 2, S. 522 und Initium-Nr 1615. 10520. Es folgen 15 Gebete (Initien im Register).
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

