\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 170\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -175\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  [{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Mechthild von Hackeborn}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Liber specialis gratiae}}\plain \f1\lang1033\fs24 ], pars 1, cap. 1, Exzerpt. (170\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Si quis horum gaudiorum me ammonuerit, pro primo tantum desideraverit, dabo ei ante mortem eius gustum mee divinitatis\plain \f1\lang1033\fs24  ... (171\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) ... \plain \f1\i\lang1033\fs24 Sequitur oracio prima\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Laudo, adoro, magnifico, glorifico et benedico te, Ihesu bone, in illo ineffabili gaudio}}\plain \f1\lang1033\fs24  ... 5 Gebete. Druck: Revelationes Gertrudianae et Mechtildianae. Ed. Solesmes, Bd 2, 1877, S. 65-67.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Arial;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 175\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -178\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Pater-noster-Gebet}}\plain \f1\lang1033\fs24 . (175\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Hanc oracionem humanum cor non excogitavit, sed deus revelavit et dicas tria Pater noster. Primum orabis pro ini\plain \f1\lang1033\fs24 (175\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 )\plain \f1\i\lang1033\fs24 micis\plain \f1\lang1033\fs24  ...\u8249 \'8b. \plain \f1\i\lang1033\fs24 Pater dimitte illis quia nesciunt quid faciunt.\plain \f1\lang1033\fs24  \u8250 \'9b\plain \f1\i\lang1033\fs24 Deinde oracionem sequentem\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Oro te, domine Ihesu Christe, fili dei vivi amantissime, per illam caritatem}}\plain \f1\lang1033\fs24  ... (176\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) ... \u8250 \'9b\plain \f1\i\lang1033\fs24 Secundum Pater noster, ut donet tibi dominus pacienciam in adversis\plain \f1\lang1033\fs24  ...\u8249 \'8b. \plain \f1\i\lang1033\fs24 Adduxerunt Ihesum in calvarie locum sibi crucem baiulantem\plain \f1\lang1033\fs24  ... \u8250 \'9b\plain \f1\i\lang1033\fs24 Et sequitur secunda oracio\plain \f1\lang1033\fs24 \u8249 \'8b. (176\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Oro te, domine Ihesu Christe amantissime, per dulce et amabile pondus sanctissime crucis}}\plain \f1\lang1033\fs24  ... \u8250 \'9b\plain \f1\i\lang1033\fs24 Tunc sequitur\plain \f1\lang1033\fs24  (177\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 tercium Pater noster. Et commendabis animam et corpus tuum deo\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Commendo tibi, domine Ihesu Christe, fili dei vivi amantissime, hodie et cottidie in manus tuam (!) animam et corpus meum}}\plain \f1\lang1033\fs24  ... (177\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) ... \u8250 \'9b\plain \f1\i\lang1033\fs24 Pater noster. Sequitur oracio\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Gloria tibi, domine, qui expansis in cruce manibus traxisti omnia ad te}}\plain \f1\lang1033\fs24  ...
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Arial;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 178\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -186\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Oratio ad BMV}}\plain \f1\lang1033\fs24 . (178\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Quicumque hanc oracionem subscriptam legerit nonaginta diebus sic, quod nulla die obmiserit, quidquid per hac pecierit, impetrabit. Unum Ave Maria pro scriptore propter deum. Sequitur oracio valde utilis de beata virgine Maria\plain \f1\lang1033\fs24  ... (178\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) ...\u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 O domina mea, sancta Maria, virgo virginum perpetua et mater summe benignitatis et misericordie}}\plain \f1\i\lang1033\fs24 , per illum qui animam tuam pertransivit gladius \plain \f1\lang1033\fs24 (!)\plain \f1\i\lang1033\fs24  doloris\plain \f1\lang1033\fs24  ... Vgl. Wilmart, Auteurs, S. 516 Anm. 1 Nr 5. Direkt angeh\u228 \'e4ngt: (185\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Hic forma peticionem tuam. Qua finita subsequitur oracio ista\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Obsecro te eciam, domina mea et mater pietate plenissima, ut michi obtineas}}\plain \f1\lang1033\fs24  ...
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

