\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 186\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -198\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Salutationes BMV}}\plain \f1\lang1033\fs24 . (186\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Has dulcissimas salutaciones didicit monialis quedam a beata virgine\plain \f1\lang1033\fs24  ... (186\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) ...\u8249 \'8b. (1.) \plain \f1\i\lang1033\fs24 Per illud letissimum Gabrielis nuncium tue nostreque salutis exordium\plain \f1\lang1033\fs24  ... (187\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) ... \plain \f1\i\lang1033\fs24 Ave Maria\plain \f1\lang1033\fs24  ... \u8250 \'9b\plain \f1\i\lang1033\fs24 Sequitur alia oracio\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Obsecro te, o pijssima mater dei Maria, ut apud filium (187v) tuum Ihesum Christum commendes me}}\plain \f1\i\lang1033\fs24  famulam tuam\plain \f1\lang1033\fs24  ... (2.) \plain \f1\i\lang1033\fs24 Per illud mirabile opus\plain \f1\lang1033\fs24  (188\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 trinitatis, quod in te operatum est\plain \f1\lang1033\fs24  ... Es folgen Salutationes zu Kindheitsgeschichte, Passion, Auferstehung und Himmelfahrt Christi, zu Pfingsten sowie zu Assumptio Mariae und ihrem Lobpreis. Schlie\u223 \'dft: (197\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) (26.) \plain \f1\i\lang1033\fs24 Per illa, o pijssima pijssimi mater dei, Maria, ut apud filium tuum Ihesum Christum mee misere N. commendes\plain \f1\lang1033\fs24  ...- (198\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) ... \plain \f1\i\lang1033\fs24 et frui post mortem eternaliter fruicionem. Amen.\plain \f1\lang1033\fs24  \u8250 \'9b\plain \f1\i\lang1033\fs24 Pater noster. Ave Maria pro scriptore propter deum etc.\plain \f1\lang1033\fs24 \u8249 \'8b.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Arial;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

