\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 198\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -215\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Psalmi graduales cum orationibus ad BMV}}\plain \f1\lang1033\fs24 . \u8250 \'9b\plain \f1\i\lang1033\fs24 Sequitur ordo quindecim graduum. Oracio prima\plain \f1\lang1033\fs24 \u8249 \'8b. AH 11, Nr 92, Str. 1-3, mit Anrufungen Mariens. Es folgen die Gradualpsalmen: Ps 119-133 (nur Anf\u228 \'e4nge), mit 15 {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6922/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Gebeten an Maria}}\plain \f1\lang1033\fs24 , darunter: (201\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) (3.) {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Precor te, pijssima virgo Maria, pro amore unigeniti filij tui}}\plain \f1\lang1033\fs24  ... \plain \f1\i\lang1033\fs24 ut intercedas\plain \f1\lang1033\fs24  ... Vgl. Barr\u233 \'e9, Pri\u232 \'e8res, S. 276 Nr 62, mit Abweichungen. (212\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) (14.) {\field{\*\fldinst HYPERLINK "hida://5650[14].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Singularis meriti sola sine exemplo mater et virgo sancta, quam dominus ita mente et corpore immolatam custodivit}}\plain \f1\lang1033\fs24  ... Beginn wie Ps.-Anselmus: Oratio 49. PL 158, Sp. 946. Die \u252 \'fcbrigen Initien im Register. Schlie\u223 \'dft (214\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) mit Magnificat. Antiphon: CAO Nr 5006. (214\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Kyrie. Pater noster. Versikel (nur Anf\u228 \'e4nge). \u8250 \'9b\plain \f1\i\lang1033\fs24 Oracio\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Letifica et adiuva nos, clementissime deus, dominice concepcionis gaudia recolentes}}\plain \f1\lang1033\fs24  ...
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

