\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 224\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -225\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Exemplum de ortu Rosarii}}\plain \f1\lang1033\fs24 . \u8250 \'9b\plain \f1\i\lang1033\fs24 Hic incipit exemplum de rosario beate Marie virginis. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Quidam religiosus raptus in celum vidit, qualiter beata gloriosa virgo Maria venit cum multis virginibus}}\plain \f1\lang1033\fs24  ...-... \plain \f1\i\lang1033\fs24 Quinquaginta Ave Maria faciunt unum rosarium eciam sine articulis\plain \f1\lang1033\fs24 \u8249 \'8b. Vollst\u228 \'e4ndig rubriziert. Exempel \u252 \'fcber die Rosenkranz-Vision des Trierer Kart\u228 \'e4users Adolf von Essen; gegen\u252 \'fcber dem 17. Exempel der Zwanzig-Exempel-Schrift etwas verk\u252 \'fcrzt: vgl. Klinkhammer, Adolf von Essen, S. 184f.; Andreas Heinz, Eine sp\u228 \'e4tmittelalterliche Exempelsammlung zur Propagierung des Trierer Kart\u228 \'e4user-Rosenkranzes (Bibl. Cusana Hs 128, fol. 134-141), in: Trierer Theologische Zeitschrift 92, 1983, S. 306-318, hier 313f., 317f. zu Exemplum V.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

