\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 225\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -233\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Rosarium BMV}}\plain \f1\scaps\lang1033\fs24 .\plain \f1\lang1033\fs24  (225\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Hic incipit rosarium\plain \f1\lang1033\fs24 \u8249 \'8b. (226\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -233\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Ave Maria, gracia plena ... Quem angelo nunciante de spiritu sancto concepisti}}\plain \f1\i\lang1033\fs24 . Amen. \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 Ave Maria \plain \f1\lang1033\fs24 ...\u8249 \'8b ... (233\plain \f1\super\lang1033\fs24 r-v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Sequitur collecta post rosarium\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Deus, qui nobis vitam unigeniti domini nostri Ihesu Christi et gloriose virginis matris eius sedula devocione in rosario recensere concedis}}\plain \f1\lang1033\fs24  ...-... \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[2]/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Et sic est finis}}\plain \f1\lang1033\fs24 \u8249 \'8b. 50 Rosenkranzklauseln in Zehnerteilung mit Schlu\u223 \'dfgebet. Druck: Meersseman, Hymnos 2, S. 157-159 Nr 18.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

