\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 13\plain \f1\super\lang1033\fs24 r-v\plain \f1\lang1033\fs24  [{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Ps.-Gregorius I. papa}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Oratio ad Christum}}\plain \f1\lang1033\fs24 ]. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Domine Ihesu Christe, adoro te in cruce pendentem}}\plain \f1\lang1033\fs24  ... Druck u.a.: Leroquais, Livres d\rquote heures 2, S. 346 Nr 1-2. 4. 7. 3. (13\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Nachtrag: Ebd., Nr 5-6.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

