\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs20 II. Bl 14: 10,5 \plain \f2\lang1024\fs20 \u180 \'b4\plain \f0\fs20  7 \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  {\field{\*\fldinst HYPERLINK "hida://bezsoz[0].4600/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat7 Marienbaum, Birgittenkloster}}\plain \f0\fs20  \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat7 um 1485}}\plain \f0\fs20  \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  Schriftraum 8,5 \plain \f2\lang1024\fs20 \u180 \'b4\plain \f0\fs20  5 \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  23 bzw. 22 Zeilen \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  schlaufenlose {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat7 Bastarda}}\plain \f0\fs20  von einer Hand (\ldblquote {\field{\*\fldinst HYPERLINK "hida://5704[1]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat7 Hybrida}}\plain \f0\fs20 \rdblquote ) \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  14\plain \f1\super\lang1033\fs20 v\plain \f0\fs20  2zeilige rote Lombarde mit einfachem Fleuronn\u233 \'e9e in Tinte; 14\plain \f1\super\lang1033\fs20 r\plain \f0\fs20  3zeilige rote Lombarde mit Fleuronn\u233 \'e9e in Tinte und wenig Gr\u252 \'fcn, Ausl\u228 \'e4ufer als {\field{\*\fldinst HYPERLINK "hida://5270[0]/?u"}{\fldrslt \plain \f0\fs20\chcbpat7 Akanthusblattranke}}\plain \f0\fs20  bis in den unteren Rand gef\u252 \'fchrt; entsprechend der Rankenornamentik in einer Hs aus Marienbaum von 1485: {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f0\fs20\chcbpat7 Westmalle, Abdijbibliotheek, Hs. 4 (olim Liturgia A 15)}}\plain \f0\fs20 , s. Guido Hendrix, Handschriftenbezit en boekengebruik. Trappisten van Westmalle 1794-1994 (Bibliotheca auctorum traductorum et scriptorum ordinis Cisterciensis 3), Leuven 1994, S. 103f. mit Farbabb. 6.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

