\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 17\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -219\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  [{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Johannes Schlitpacher}}\plain \f1\scaps\lang1033\fs24 :] {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Manuale viaticum super regulam sancti Benedicti}}\plain \f1\lang1033\fs24 . (17\plain \f1\super\lang1033\fs24 r-v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Incipit registrum in regulam sanctissimi patris nostri Benedicti\plain \f1\lang1033\fs24 \u8249 \'8b. Kapitelverzeichnis. (18\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -29\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Prolog: \u8250 \'9b\plain \f1\i\lang1033\fs24 Incipit prologus in regulam\plain \f1\lang1033\fs24  ...\u8249 \'8b. Haupttext satzweise aufgeteilt, dazu jeweils Interlinearglossen und anschlie\u223 \'dfender Kommentar. (18\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Obsculta, o filii, precepta magistri\plain \f1\lang1033\fs24  ...; Kommentar: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Regula beatissimi patri (!) nostris (!) \u8250 \'9bBenedicti\u8249 \'8b abbatis prima sui divisione dividitur}}\plain \f1\i\lang1033\fs24  in duas partes, scilicet in partem prohemialem\plain \f1\lang1033\fs24  ... (29\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) leer. (30\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -219\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Regula c. 1-73: (30\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Incipit regula\plain \f1\lang1033\fs24  ... \plain \f1\i\lang1033\fs24 cum glosa. Capitulum primum\plain \f1\lang1033\fs24 \u8249 \'8b. \plain \f1\i\lang1033\fs24 Monachorum quatuor esse genera manifestum est\plain \f1\lang1033\fs24  ...; Kommentar: \plain \f1\i\lang1033\fs24 Ab hoc primo capitulo quod est de quatuor generibus monachorum secundum eius rubricam incipit proprie regula sancti Benedicti sive pars executiva\plain \f1\lang1033\fs24  ... (219\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) -... \plain \f1\i\lang1033\fs24 Facientibus hec regna patebunt eterna,\plain \f1\lang1033\fs24  ... \plain \f1\i\lang1033\fs24 Que nobis tribuat Christus dominus noster. Amen\plain \f1\lang1033\fs24 . \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[1]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat7 Explicit manuale super regulam sanctissimi patris nostri Benedicti abbatis, scriptum per fratrem Ulricum de Augusta presbiterum et monachum professum expresse in Weyhensteven, anno domini 1450 in vigilia assumpcionis gloriose virginis Marie (14.8.)}}\plain \f1\i\lang1033\fs24  regnantibus venerabilibus patribus {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100gi/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Johanne Geyselvelder}}\plain \f1\i\lang1033\fs24  abbate anno eius 3\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  et {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100gi/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat7 Johanne Widenman}}\plain \f1\i\lang1033\fs24  priore etc.\plain \f1\lang1033\fs24 \u8249 \'8b. Zu Autor und Werk: Franz Josef Worstbrock, in: VL\plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24  8, 1992, Sp. 727-748, bes. 733; Burkhard Ellegast, Die Anf\u228 \'e4nge einer Textkritik zur Regel des heiligen Benedikt in den Kreisen der Melker Reform (15. Jh.), in: Stift Melk. Geschichte und Gegenwart, Bd 3, Melk 1983, S. 8-91, bes. 18-59. Zum Schreiber: Colophons 5, Nr 18173; zu Abt und Prior: Germania Benedictina 2, S. 324; Gentner, Weihenstephan, S. 88-96, S. 228 Nr 18.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

