\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs20 Die Hs besteht aus 2 sehr unterschiedlichen Teilen, die im 14. Jh zusammengebunden wurden \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  Bl 1-2 Vorsatzbll, bei der modernen Foliierung mitgez\u228 \'e4hlt, s. u. 1. Fragment; Nachsatzbl, s.u. 2. Fragment \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  Lagen: 2 IV\plain \f1\super\lang1033\fs20 18\plain \f0\fs20  + III\plain \f1\super\lang1033\fs20 24\plain \f0\fs20  + 4 V\plain \f1\super\lang1033\fs20 64\plain \f0\fs20  + IV\plain \f1\super\lang1033\fs20 72\plain \f0\fs20  + (IV-1)\plain \f1\super\lang1033\fs20 79\plain \f0\fs20 ; nach Bl 79 1 Bl ohne Textverlust ausgeschnitten \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  2\plain \f1\super\lang1033\fs20 r\plain \f0\fs20  Buchbindervermerk und Inhaltsverzeichnis, s.u., gotische Kursive, 14. Jh, 3. Viertel \plain \f1\super\lang1033\fs20 .\plain \f0\fs20  24\plain \f1\super\lang1033\fs20 v\plain \f0\fs20 . 79\plain \f1\super\lang1033\fs20 r-v\plain \f0\fs20  Nachtr\u228 \'e4ge in humanistischer Kursive von einer Hand, 16. Jh, 3. Viertel.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Arial;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

