\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (4\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -16\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat7 Kalendar}}\plain \f1\lang1033\fs24 . Relativ sparsam besetzt; weist auf Br\u252 \'fcgge, vgl. Wieck, Time sanctified, S. 153-156. Bemerkenswert: \u8250 \'9b\plain \f1\i\lang1033\fs24 Vincenti\plain \f1\lang1033\fs24  (!) \plain \f1\i\lang1033\fs24 m.\plain \f1\lang1033\fs24 \u8249 \'8b (22.1.), \plain \f1\i\lang1033\fs24 Aldegundis\plain \f1\lang1033\fs24  (30.1.), \u8250 \'9b\plain \f1\i\lang1033\fs24 Amandi\plain \f1\lang1033\fs24 \u8249 \'8b (6.2.), [Trsl.] \plain \f1\i\lang1033\fs24 s. Augustini\plain \f1\lang1033\fs24  (28.2.), \u8250 \'9b\plain \f1\i\lang1033\fs24 Benedicti\plain \f1\lang1033\fs24 \u8249 \'8b (21.3.), \plain \f1\i\lang1033\fs24 Balbine\plain \f1\lang1033\fs24  (31.3.), \plain \f1\i\lang1033\fs24 Victoris\plain \f1\lang1033\fs24  (20.4.), \plain \f1\i\lang1033\fs24 s. Nicolay\plain \f1\lang1033\fs24  (10.5. statt 9.5.), \plain \f1\i\lang1033\fs24 Brandari\plain \f1\lang1033\fs24  (!, 17.5., so auch Br\u252 \'fcgge), \plain \f1\i\lang1033\fs24 Bernardini\plain \f1\lang1033\fs24  (Senen., 21.5. statt 20.5., can. 1450), \u8250 \'9b\plain \f1\i\lang1033\fs24 Barnabe ap.\plain \f1\lang1033\fs24 \u8249 \'8b (11.6.), \u8250 \'9b\plain \f1\i\lang1033\fs24 Basilii\plain \f1\lang1033\fs24 \u8249 \'8b (14.6.), \u8250 \'9b[Trsl.] \plain \f1\i\lang1033\fs24 s. Thome\plain \f1\lang1033\fs24 \u8249 \'8b. (3.7.), \u8250 \'9b[Depositio] \plain \f1\i\lang1033\fs24 Benedicti\plain \f1\lang1033\fs24 \u8249 \'8b (11.7.), \plain \f1\i\lang1033\fs24 Bernardi\plain \f1\lang1033\fs24  (20.8.!, nicht 27.8. wie Br\u252 \'fcgge), \u8250 \'9b\plain \f1\i\lang1033\fs24 Egidii\plain \f1\lang1033\fs24 \u8249 \'8b (1.9.), \plain \f1\i\lang1033\fs24 Bertini\plain \f1\lang1033\fs24  (5.9.), \plain \f1\i\lang1033\fs24 Nicolay\plain \f1\lang1033\fs24  (Tolentini, 10.9., can. 1446), \u8250 \'9b\plain \f1\i\lang1033\fs24 Remigii et Bavonis\plain \f1\lang1033\fs24 \u8249 \'8b (1.10.), \u8250 \'9b\plain \f1\i\lang1033\fs24 Dyonisi\plain \f1\lang1033\fs24  (!) \plain \f1\i\lang1033\fs24 ep.\plain \f1\lang1033\fs24 \u8249 \'8b (9.10.), \u8250 \'9b\plain \f1\i\lang1033\fs24 Donationi ep.\plain \f1\lang1033\fs24 \u8249 \'8b (14.10.), \u8250 \'9b\plain \f1\i\lang1033\fs24 Clementis pp.\plain \f1\lang1033\fs24 \u8249 \'8b (23.11.), \u8250 \'9b\plain \f1\i\lang1033\fs24 Eligii ep.\plain \f1\lang1033\fs24 \u8249 \'8b (1.12.), \u8250 \'9b\plain \f1\i\lang1033\fs24 Nichasii ep.\plain \f1\lang1033\fs24 \u8249 \'8b (14.12.), \plain \f1\i\lang1033\fs24 Lazari\plain \f1\lang1033\fs24  (17.12.).
